pub unsafe fn tinfl_decompress_mem_to_callback(
    mut pIn_buf: *const c_void,
    mut pIn_buf_size: *mut size_t,
    mut pPut_buf_func: tinfl_put_buf_func_ptr,
    mut pPut_buf_user: *mut c_void,
    mut flags: c_int,
) -> c_int {
    let mut result: c_int = 0;
    let mut decomp: tinfl_decompressor = core::mem::zeroed();
    let p_dict: *mut mz_uint8 = malloc(TINFL_LZ_DICT_SIZE as size_t) as *mut mz_uint8;
    let mut in_buf_ofs: size_t = 0;
    let mut dict_ofs: size_t = 0;

    if p_dict.is_null() {
        return TINFL_STATUS_FAILED as c_int;
    }

    memset(p_dict as *mut c_void, 0, TINFL_LZ_DICT_SIZE as size_t);
    decomp.m_state = 0;

    let base_in = pIn_buf as *const mz_uint8;
    let callback = pPut_buf_func.expect("non-null function pointer");
    let decomp_flags = (flags
        & !(TINFL_FLAG_HAS_MORE_INPUT as c_int | TINFL_FLAG_USING_NON_WRAPPING_OUTPUT_BUF as c_int))
        as mz_uint32;
    let dict_mask = (TINFL_LZ_DICT_SIZE - 1 as c_int) as size_t;

    loop {
        let mut in_buf_size: size_t = (*pIn_buf_size).wrapping_sub(in_buf_ofs);
        let mut dst_buf_size: size_t = (TINFL_LZ_DICT_SIZE as size_t).wrapping_sub(dict_ofs);

        let status: tinfl_status = tinfl_decompress(
            &raw mut decomp,
            // SAFETY: base_in points to the caller-provided input buffer, and in_buf_ofs is maintained within the remaining input size accounting used by the original code.
            unsafe { base_in.add(in_buf_ofs) },
            &raw mut in_buf_size,
            p_dict,
            // SAFETY: p_dict points to a 32K allocation, and dict_ofs is always masked/wrapped to stay within that allocation as in the original code.
            unsafe { p_dict.add(dict_ofs) },
            &raw mut dst_buf_size,
            decomp_flags,
        );

        in_buf_ofs = in_buf_ofs.wrapping_add(in_buf_size);

        if dst_buf_size != 0
            && callback(
                // SAFETY: same bounds reasoning as above for p_dict.add(dict_ofs); callback only receives the produced slice start.
                unsafe { p_dict.add(dict_ofs) as *const c_void },
                dst_buf_size as c_int,
                pPut_buf_user,
            ) == 0
        {
            break;
        }

        if status as c_int != TINFL_STATUS_HAS_MORE_OUTPUT as c_int {
            result = (status as c_int == TINFL_STATUS_DONE as c_int) as c_int;
            break;
        }

        dict_ofs = dict_ofs.wrapping_add(dst_buf_size) & dict_mask;
    }

    free(p_dict as *mut c_void);
    *pIn_buf_size = in_buf_ofs;
    result
}
