        flags >>= 1;
    }

    put_bits(
        &mut bit_buffer,
        &mut bits_in,
        &mut out_ptr,
        out_end,
        litlen_codes[256] as mz_uint,
        litlen_sizes[256] as mz_uint,
    );

    d_view.m_bit_buffer = bit_buffer;
    d_view.m_bits_in = bits_in;
    d_view.m_pOutput_buf = out_ptr;

    (out_ptr < out_end) as c_int
}
